SELECT o.name, o.type, f.feat
FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id
CROSS APPLY (VALUES ('STRING_SPLIT','%STRING[_]SPLIT%'),('OPENJSON','%OPENJSON%'),('GENERATE_SERIES','%GENERATE[_]SERIES%'),('STRING_AGG','%STRING[_]AGG%'),('WITHIN GROUP','%WITHIN GROUP%'),
 ('TRIM(','%[^A-Za-z_]TRIM(%'),('CONCAT_WS','%CONCAT[_]WS%'),('DATE_BUCKET','%DATE[_]BUCKET%'),('GREATEST','%GREATEST(%'),('LEAST','%[^A-Za-z_]LEAST(%'),('IS DISTINCT FROM','%IS%DISTINCT FROM%'),
 ('TRANSLATE(','%[^A-Za-z_]TRANSLATE(%'),('CREATE OR ALTER','%CREATE OR ALTER%'),('DROP IF EXISTS','%DROP % IF EXISTS%'),('FORMAT(','%[^A-Za-z_]FORMAT(%'),('TRY_CONVERT','%TRY[_]CONVERT%'),('JSON_VALUE','%JSON[_]VALUE%'),('DATEFROMPARTS','%DATEFROMPARTS%'),('EOMONTH','%EOMONTH%'),('IIF(','%[^A-Za-z_]IIF(%'),('THROW','%THROW%'),('SESSION_CONTEXT','%SESSION[_]CONTEXT%'),('DATEDIFF_BIG','%DATEDIFF[_]BIG%'),('APPROX_COUNT','%APPROX[_]COUNT%'),('STRING_ESCAPE','%STRING[_]ESCAPE%'),('COMPRESS','%[^A-Za-z_]COMPRESS(%'),('AT TIME ZONE','%AT TIME ZONE%'),('UTF8 collation','%UTF8%'),('OPTIMIZE_FOR_SEQUENTIAL_KEY','%OPTIMIZE[_]FOR[_]SEQUENTIAL%'),('INLINE=','%INLINE%=%')) f(feat,pat)
WHERE m.definition LIKE f.pat AND o.name NOT LIKE '%[_]OLD[_]%'
ORDER BY f.feat, o.name;
